package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;
import com.vandorlabs.propulsion.*;
import java.nio.file.*;
import java.util.Random;
/** Compares all actual released billboard words, then measures the same primitive emission with a live sink. */
public final class PropulsionBillboardChecks {
 private static int profiles,fields;private static volatile int consumed;
 private static void need(boolean ok,String text){if(!ok)throw new AssertionError("Billboard profile="+profiles+" "+text);}
 private static final class Sink implements PropulsionBillboard.Sink {final int[] words=new int[28];int at;public void vertex(float x,float y,float z,float u,float v,int color,int light){words[at++]=Float.floatToRawIntBits(x);words[at++]=Float.floatToRawIntBits(y);words[at++]=Float.floatToRawIntBits(z);words[at++]=Float.floatToRawIntBits(u);words[at++]=Float.floatToRawIntBits(v);words[at++]=color;words[at++]=light;}void clear(){at=0;}}
 public static void main(String[] args)throws Exception{var sink=new Sink();try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){var row=JsonParser.parseString(line).getAsJsonObject();int style=row.get("style").getAsInt();var state=new PropulsionParticle.State(8.5,90.5,8.5,row.get("face").getAsInt(),style%2==0?0xff8a24:0x4debff,style,.17F,1.25F,new Random(row.get("seed").getAsLong()));for(int i=0;i<row.get("age").getAsInt();i++)state.tickAir();var rotations=row.getAsJsonArray("rotations");float[] r=new float[5];for(int i=0;i<5;i++)r[i]=Float.intBitsToFloat(rotations.get(i).getAsInt());sink.clear();PropulsionBillboard.emit(state,Float.intBitsToFloat(row.get("partial").getAsInt()),8,90,5,r[0],r[1],r[2],r[3],r[4],sink);var expected=row.getAsJsonArray("words");need(sink.at==28&&expected.size()==28,"four complete Source records");for(int i=0;i<28;i++){need(sink.words[i]==expected.get(i).getAsInt(),"word="+i+" actual="+sink.words[i]+" expected="+expected.get(i));fields++;}profiles++;}}need(profiles==5760,"complete Source profiles");var state=new PropulsionParticle.State(8.5,90.5,8.5,2,0xc36aff,2,.17F,1.25F,new Random(0));for(int i=0;i<20000;i++){sink.clear();PropulsionBillboard.emit(state,.37F,8,90,5,1,1,0,0,0,sink);consumed=sink.words[0];}var meter=(com.sun.management.ThreadMXBean)java.lang.management.ManagementFactory.getThreadMXBean();meter.setThreadAllocatedMemoryEnabled(true);long thread=Thread.currentThread().threadId(),before=meter.getThreadAllocatedBytes(thread);for(int i=0;i<4096;i++){sink.clear();PropulsionBillboard.emit(state,.37F,8,90,5,1,1,0,0,0,sink);consumed=sink.words[0];}long bytes=meter.getThreadAllocatedBytes(thread)-before;need(bytes==0,"warm emission allocation="+bytes);System.out.println("Native Source billboard PASS profiles="+profiles+" exactWords="+fields+" costQuads4096 vertices=16384 allocated="+bytes);}
}
